import React, { useState, useEffect, useRef, useCallback } from 'react';

// Helper to determine if a note is a black key
const isBlackKey = (noteIdentifier) => {
  // Black keys are C#, D#, F#, G#, A#
  return noteIdentifier.includes('#');
};

export default function KeyboardUI({
  noteIdentifiers = [],
  onNotePressed = () => {},
  onNoteReleased = () => {},
}) {
  const [highlightedNotes, setHighlightedNotes] = useState(new Set());

  // Use refs for callbacks to ensure stable event handlers without re-creating them
  const onNotePressedRef = useRef(onNotePressed);
  const onNoteReleasedRef = useRef(onNoteReleased);

  useEffect(() => {
    onNotePressedRef.current = onNotePressed;
  }, [onNotePressed]);

  useEffect(() => {
    onNoteReleasedRef.current = onNoteReleased;
  }, [onNoteReleased]);

  // Internal capability: highlightKey
  const highlightKey = useCallback((noteIdentifier) => {
    setHighlightedNotes((prev) => {
      const newSet = new Set(prev);
      newSet.add(noteIdentifier);
      return newSet;
    });
  }, []);

  // Internal capability: unhighlightKey
  const unhighlightKey = useCallback((noteIdentifier) => {
    setHighlightedNotes((prev) => {
      const newSet = new Set(prev);
      newSet.delete(noteIdentifier);
      return newSet;
    });
  }, []);

  const handlePointerDown = useCallback((noteIdentifier) => {
    highlightKey(noteIdentifier);
    onNotePressedRef.current(noteIdentifier);
  }, [highlightKey]);

  const handlePointerUp = useCallback((noteIdentifier) => {
    unhighlightKey(noteIdentifier);
    onNoteReleasedRef.current(noteIdentifier);
  }, [unhighlightKey]);

  // Define key dimensions and offsets
  const WHITE_KEY_WIDTH_PX = 48;
  const BLACK_KEY_WIDTH_PX = 32;
  const WHITE_KEY_HEIGHT_PX = 192;
  const BLACK_KEY_HEIGHT_PX = 128;
  const KEY_SPACING_PX = 2; // Gap between white keys

  let whiteKeyCount = 0; // Tracks how many white keys have been processed
  const keyElementsWithPositions = [];

  noteIdentifiers.forEach((noteIdentifier) => {
    const isBlack = isBlackKey(noteIdentifier);
    const isHighlighted = highlightedNotes.has(noteIdentifier);

    let keyClasses = "absolute cursor-pointer rounded-b-md transition-all duration-75 ease-out group";
    let labelClasses = "absolute bottom-2 text-xs opacity-0 group-hover:opacity-100 transition-opacity duration-150";
    let keyStyle = {};

    if (!isBlack) {
      keyClasses += " bg-white border border-gray-300 shadow-sm z-0";
      keyClasses += ` w-[${WHITE_KEY_WIDTH_PX}px] h-[${WHITE_KEY_HEIGHT_PX}px]`;
      labelClasses += " text-gray-700 left-1/2 -translate-x-1/2";
      if (isHighlighted) {
        keyClasses += " bg-blue-300 shadow-lg scale-y-95";
      }
      keyStyle.left = `${whiteKeyCount * (WHITE_KEY_WIDTH_PX + KEY_SPACING_PX)}px`;
      whiteKeyCount++; // Increment after positioning a white key
    } else {
      keyClasses += " bg-gray-900 border-2 border-gray-700 shadow-md z-10";
      keyClasses += ` w-[${BLACK_KEY_WIDTH_PX}px] h-[${BLACK_KEY_HEIGHT_PX}px]`;
      labelClasses += " text-white left-1/2 -translate-x-1/2";
      if (isHighlighted) {
        keyClasses += " bg-blue-600 shadow-lg scale-y-95";
      }

      // Black key positioning:
      // It's positioned relative to the *last* white key that was processed.
      // The `whiteKeyCount` at this point represents the number of white keys *before* this black key.
      // So, the `left` of the white key it follows is `(whiteKeyCount - 1) * (WHITE_KEY_WIDTH_PX + KEY_SPACING_PX)`.
      // Then add `WHITE_KEY_WIDTH_PX - BLACK_KEY_WIDTH_PX / 2` to center it.
      const precedingWhiteKeyLeft = (whiteKeyCount - 1) * (WHITE_KEY_WIDTH_PX + KEY_SPACING_PX);
      keyStyle.left = `${precedingWhiteKeyLeft + WHITE_KEY_WIDTH_PX - (BLACK_KEY_WIDTH_PX / 2)}px`;
    }

    keyElementsWithPositions.push({
      noteIdentifier,
      isBlack,
      isHighlighted,
      keyClasses,
      labelClasses,
      keyStyle,
    });
  });

  // Calculate total width for the keyboard container
  const totalKeyboardWidth = whiteKeyCount > 0 ? (whiteKeyCount * (WHITE_KEY_WIDTH_PX + KEY_SPACING_PX) - KEY_SPACING_PX) : 0;

  return (
    <div className="relative flex justify-center items-center h-64 bg-gray-800 rounded-lg p-4 overflow-hidden">
      <div className="relative h-full" style={{ width: `${totalKeyboardWidth}px` }}> {/* Container for keys */}
        {keyElementsWithPositions.map(({ noteIdentifier, isBlack, isHighlighted, keyClasses, labelClasses, keyStyle }) => (
          <div
            key={noteIdentifier}
            className={`${keyClasses} ${isBlack ? 'top-0' : 'top-0'}`} // Black keys are elevated, white keys are base
            style={keyStyle}
            onPointerDown={() => handlePointerDown(noteIdentifier)}
            onPointerUp={() => handlePointerUp(noteIdentifier)}
            // Optional: Release highlight if pointer leaves while pressed
            onPointerLeave={() => isHighlighted && handlePointerUp(noteIdentifier)}
          >
            <span className={labelClasses}>{noteIdentifier}</span>
          </div>
        ))}
      </div>
    </div>
  );
}